import datetime

holidays = {datetime.date(2026,10,12)}

def is_business_day(d):
    return d.weekday() < 5 and d not in holidays

def add_business_days_inclusive(start, n):
    """Return the date of the nth business day counting start as day 1."""
    d = start
    count = 0
    while True:
        if is_business_day(d):
            count += 1
            if count == n:
                return d
        d += datetime.timedelta(days=1)

def next_business_day(d):
    d += datetime.timedelta(days=1)
    while not is_business_day(d):
        d += datetime.timedelta(days=1)
    return d

phases = [("Discovery",3), ("Build",6), ("QA",4), ("Release",1)]
start = datetime.date(2026,10,5)
assert is_business_day(start), "start date is not a business day!"

cur_start = start
for name, dur in phases:
    end = add_business_days_inclusive(cur_start, dur)
    print(f"{name}: start={cur_start} ({cur_start.strftime('%A')}), duration={dur} business days, end={end} ({end.strftime('%A')})")
    cur_start = next_business_day(end)

print("Launch date (end of last phase):", end)
EOF
